import { Term } from './types';

// The booking system marks the spring terms as not bookable on the web by
// mistake; show them anyway until it is fixed there.
const ALWAYS_VISIBLE = ['T-101', 'T-102', 'T-103'];

export function visibleTerms(terms: Term[]): Term[] {
  return terms.filter((t) => t.availableOnWeb || ALWAYS_VISIBLE.includes(t.id));
}
